using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class BusShelterVerify{static BusShelterVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BusShelterVerify.request"))return;var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).ToArray();var target=all.FirstOrDefault(g=>g.name=="Bus stop - City 02 - polySurface842"&&AssetDatabase.GetAssetPath(g.sharedMesh).Contains("BusShelterUpgrade"));if(!target)return;File.Delete("BusShelterVerify.request");try{var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);var b=target.sharedMesh.bounds;var p=target.transform.TransformPoint(new Vector3(b.center.x,b.center.y,b.min.z+1.4f));var front=target.transform.TransformDirection(Vector3.down).normalized;var right=target.transform.TransformDirection(Vector3.right).normalized;capture.Invoke(null,new object[]{scene,p+front*6-right*3+Vector3.up*.25f,p,"Bus-Shelter-Upgraded-Front"});capture.Invoke(null,new object[]{scene,p-front*7-right*3+Vector3.up*1.4f,p,"Bus-Shelter-Upgraded-Back"});var ctrl=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;try{ctrl.ApplyNight();capture.Invoke(null,new object[]{scene,p+front*6-right*3+Vector3.up*.25f,p,"Bus-Shelter-Upgraded-Night"});}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();}var copies=all.Where(f=>f.sharedMesh==target.sharedMesh).ToArray();File.WriteAllLines("FinalEnvironmentRoadReview/BusShelterVerified.txt",new[]{"Shared city copies="+copies.Length+" all have LOD="+copies.All(f=>f.GetComponent<LODGroup>())+" shader errors="+ShaderUtil.ShaderHasError(target.GetComponent<Renderer>().sharedMaterial.shader),"Source prefab mesh="+AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/Bus stop.prefab").GetComponent<MeshFilter>().sharedMesh.name}.Concat(copies.Select(f=>f.name+" source="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(f.gameObject)+" meshOverride="+new SerializedObject(f).FindProperty("m_Mesh").prefabOverride+" lights="+f.GetComponentsInChildren<Light>(true).Length)));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BusShelterVerified.txt",e.ToString());Debug.LogException(e);}}}
